#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <cooperative_groups.h>
namespace cg = cooperative_groups;

#define THREADS 256

__global__ void ln_coop_kernel(const float4* __restrict__ x4,
                               const float4* __restrict__ w4,
                               const float4* __restrict__ b4,
                               float4* __restrict__ y4,
                               float* __restrict__ gsum,
                               float* __restrict__ gsq,
                               int rows, long long N4, int chunks_per_row, float eps) {
    cg::grid_group grid = cg::this_grid();
    __shared__ float ssum[THREADS/32];
    __shared__ float ssq[THREADS/32];

    long long chunk_size4 = (N4 + chunks_per_row - 1) / chunks_per_row; // in float4 units
    int total_chunks = rows * chunks_per_row;

    // phase 1
    for (int c = blockIdx.x; c < total_chunks; c += gridDim.x) {
        int r = c / chunks_per_row;
        int cp = c % chunks_per_row;
        long long start = (long long)cp * chunk_size4;
        long long end = min(start + chunk_size4, N4);
        const float4* xp = x4 + (long long)r * N4;
        float s = 0.f, sq = 0.f;
        for (long long i = start + threadIdx.x; i < end; i += blockDim.x) {
            float4 v = xp[i];
            s += v.x + v.y + v.z + v.w;
            sq += v.x*v.x + v.y*v.y + v.z*v.z + v.w*v.w;
        }
        // block reduce
        ... warp shuffle reduce s and sq, write lane0 to shared, then first warp reduces
        if (threadIdx.x == 0) {
            atomicAdd(&gsum[r], s);
            atomicAdd(&gsq[r], sq);
        }
    }
    grid.sync();
    // compute stats: thread computes for all rows (cheap): each block reads gsum/gsq
    // store to shared or registers: rows <= 64 assumed; loop per row when processing chunk
    // phase 2
    for (int c = blockIdx.x; c < total_chunks; c += gridDim.x) {
        int r = c / chunks_per_row;
        int cp = c % chunks_per_row;
        float mean = gsum[r] / (float)(N4*4);
        float var = gsq[r] / (float)(N4*4) - mean*mean;
        float rstd = rsqrtf(var + eps);
        long long start = (long long)cp * chunk_size4;
        long long end = min(start + chunk_size4, N4);
        const float4* xp = x4 + (long long)r * N4;
        const float4* wp = w4;
        const float4* bp = b4;
        float4* yp = y4 + (long long)r * N4;
        for (long long i = start + threadIdx.x; i < end; i += blockDim.x) {
            float4 v = xp[i];
            float4 ww = wp[i];
            float4 bb = bp[i];
            float4 o;
            o.x = (v.x - mean) * rstd * ww.x + bb.x;
            ...
            yp[i] = o;
        }
    }
}
