import torch
import torch.nn as nn
import triton
from torch.utils.cpp_extension import load_inline

cuda_src = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

#define FULL_MASK 0xffffffffu

// Kernel A: partial sums per (row, chunk)
__global__ void partial_kernel(const float4* __restrict__ x4,
                               float* __restrict__ ps,
                               float* __restrict__ psq,
                               int n4, int chunks) {
    int row = blockIdx.y;
    int chunk = blockIdx.x;
    int chunk_size = (n4 + chunks - 1) / chunks;
    int start = chunk * chunk_size;
    int end = min(start + chunk_size, n4);
    const float4* xr = x4 + (long)row * (long)n4;
    float s = 0.f, sq = 0.f;
    for (int i = start + threadIdx.x; i < end; i += blockDim.x) {
        float4 v = xr[i];
        s += v.x + v.y + v.z + v.w;
        sq += v.x*v.x + v.y*v.y + v.z*v.z + v.w*v.w;
    }
    __shared__ float sh_s[32];
    __shared__ float sh_q[32];
    for (int off = 16; off > 0; off >>= 1) {
        s += __shfl_down_sync(FULL_MASK, s, off);
        sq += __shfl_down_sync(FULL_MASK, sq, off);
    }
    int lane = threadIdx.x & 31;
    int warp = threadIdx.x >> 5;
    if (lane == 0) { sh_s[warp] = s; sh_q[warp] = sq; }
    __syncthreads();
    int nwarp = (blockDim.x + 31) >> 5;
    if (warp == 0) {
        s = (lane < nwarp) ? sh_s[lane] : 0.f;
        sq = (lane < nwarp) ? sh_q[lane] : 0.f;
        for (int off = 16; off > 0; off >>= 1) {
            s += __shfl_down_sync(FULL_MASK, s, off);
            sq += __shfl_down_sync(FULL_MASK, sq, off);
        }
        if (lane == 0) {
            ps[row * chunks + chunk] = s;
            psq[row * chunks + chunk] = sq;
        }
    }
}

// Kernel B: finalize + normalize. reverse=1 remaps chunks to hit L2-warm tail first.
template<int REVERSE>
__global__ void norm_kernel(const float4* __restrict__ x4,
                            const float4* __restrict__ w4,
                            const float4* __restrict__ b4,
                            float4* __restrict__ y4,
                            const float* __restrict__ ps,
                            const float* __restrict__ psq,
                            float* __restrict__ mean_out,
                            float* __restrict__ rstd_out,
                            int n4, int chunks, float eps) {
    int row = blockIdx.y;
    int chunk = REVERSE ? (gridDim.x - 1 - (int)blockIdx.x) : (int)blockIdx.x;
    int chunk_size = (n4 + chunks - 1) / chunks;
    int start = chunk * chunk_size;
    int end = min(start + chunk_size, n4);
    __shared__ float s_mean, s_rstd;
    if (threadIdx.x == 0) {
        float total = 0.f, totalsq = 0.f;
        for (int c = 0; c < chunks; ++c) {
            total += ps[row * chunks + c];
            totalsq += psq[row * chunks + c];
        }
        float n = (float)n4 * 4.0f;
        float mean = total / n;
        float var = totalsq / n - mean * mean;
        s_mean = mean;
        s_rstd = rsqrtf(var + eps);
    }
    __syncthreads();
    float mean = s_mean;
    float rstd = s_rstd;
    const float4* xr = x4 + (long)row * (long)n4;
    float4* yr = y4 + (long)row * (long)n4;
    for (int i = start + threadIdx.x; i < end; i += blockDim.x) {
        float4 v = xr[i];
        float4 wv = w4[i];
        float4 bv = b4[i];
        float4 o;
        o.x = (v.x - mean) * rstd * wv.x + bv.x;
        o.y = (v.y - mean) * rstd * wv.y + bv.y;
        o.z = (v.z - mean) * rstd * wv.z + bv.z;
        o.w = (v.w - mean) * rstd * wv.w + bv.w;
        yr[i] = o;
    }
}

torch::Tensor ln_two(torch::Tensor x, torch::Tensor w, torch::Tensor b,
                     torch::Tensor ps, torch::Tensor psq,
                     double eps, int64_t chunks, int64_t blockA, int64_t blockB, int64_t rev) {
    auto y = torch::empty_like(x);
    int64_t M = x.size(0);
    int64_t N = x.numel() / M;
    int n4 = (int)(N / 4);
    dim3 grid((unsigned)chunks, (unsigned)M);
    auto stream = at::cuda::getCurrentCUDAStream();
    partial_kernel<<<grid, (int)blockA, 0, stream>>>(
        (const float4*)x.data_ptr<float>(), ps.data_ptr<float>(), psq.data_ptr<float>(), n4, (int)chunks);
    if (rev) {
        norm_kernel<1><<<grid, (int)blockB, 0, stream>>>(
            (const float4*)x.data_ptr<float>(),
            (const float4*)w.data_ptr<float>(),
            (const float4*)b.data_ptr<float>(),
            (float4*)y.data_ptr<float>(),
            ps.data_ptr<float>(), psq.data_ptr<float>(), nullptr, nullptr, n4, (int)chunks, (float)eps);
    } else {
        norm_kernel<0><<<grid, (int)blockB, 0, stream>>>(
            (const float4*)x.data_ptr<float>(),
            (const float4*)w.data_ptr<float>(),
            (const float4*)b.data_ptr<float>(),
            (float4*)y.data_ptr<float>(),
            ps.data_ptr<float>(), psq.data_ptr<float>(), nullptr, nullptr, n4, (int)chunks, (float)eps);
    }
    return y;
}

__global__ void read_kernel(const float4* __restrict__ x4, float* __restrict__ out, long n4tot) {
    long i = (long)blockIdx.x * blockDim.x + threadIdx.x;
    long stride = (long)gridDim.x * blockDim.x;
    float s = 0.f;
    for (; i < n4tot; i += stride) {
        float4 v = x4[i];
        s += v.x + v.y + v.z + v.w;
    }
    if (s == 12345.678f) out[0] = s;
}

torch::Tensor read_bw(torch::Tensor x) {
    auto out = torch::zeros({1}, x.options());
    long n4tot = x.numel() / 4;
    auto stream = at::cuda::getCurrentCUDAStream();
    read_kernel<<<4096, 256, 0, stream>>>((const float4*)x.data_ptr<float>(), out.data_ptr<float>(), n4tot);
    return out;
}
'''

cpp_src = 'torch::Tensor ln_two(torch::Tensor x, torch::Tensor w, torch::Tensor b, torch::Tensor ps, torch::Tensor psq, double eps, int64_t chunks, int64_t blockA, int64_t blockB, int64_t rev);\ntorch::Tensor read_bw(torch::Tensor x);'

mod = load_inline(name='ln_two_cuda', cpp_sources=cpp_src, cuda_sources=cuda_src,
                  functions=['ln_two', 'read_bw'], extra_cuda_cflags=['-O3'], verbose=False)

B, F, D1, D2 = 16, 64, 256, 256
N = F * D1 * D2

