    ln = nn.LayerNorm((F, D1, D2)).cuda()
    w, b, eps = ln.weight, ln.bias, ln.eps
    ref = ln(x)
    results = []
    for chunks in [32, 64, 128]:
        ps = torch.empty((B, chunks), device='cuda')
        psq = torch.empty((B, chunks), device='cuda')
        for bA in [256, 512]:
