                    fn = lambda: mod.ln_two(x, w, b, ps, psq, eps, chunks, bA, bB, rev)
                    out = fn()
                    ok = torch.allclose(ref, out, atol=1e-4, rtol=1e-4)
                    if not ok:
                        print('FAIL', chunks, bA, bB, rev)
                        continue
                    ms = triton.testing.do_bench(fn, warmup=10, rep=50)
                    results.append((ms, chunks, bA, bB, rev))
    results.sort()
    for r in results[:10]:
        print(f'{r[0]:.4f} ms chunks={r[1]} blockA={r[2]} blockB={r[3]} rev={r[4]}')
    ms_read = triton.testing.do_bench(lambda: mod.read_bw(x), warmup=10, rep=50)
    print(f'pure read 268MB: {ms_read:.4f} ms -> {268.4/ms_read:.0f} GB/s')
    ms_native = triton.testing.do_bench(lambda: ln(x), warmup=10, rep=50)
